import{_ as t,a0 as p,w as o,s as d,ao as c,I as l,x as i,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"使用 split 命令分割 Linux 文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 split 命令分割 Linux 文件 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 split 命令分割 Linux 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 split 命令分割 Linux 文件 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191210 Breaking Linux files into pieces with the split command","title":"使用 split 命令分割 Linux 文件","tag":"201912","desc":""},"relativePath":"201912/20191210 Breaking Linux files into pieces with the split command.md","filePath":"[post].md"}'),g={name:"201912/20191210 Breaking Linux files into pieces with the split command.md"};function r(h,s,f,b,k,u){const a=p("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="使用-split-命令分割-linux-文件" tabindex="-1">使用 split 命令分割 Linux 文件 <a class="header-anchor" href="#使用-split-命令分割-linux-文件" aria-label="Permalink to “使用 split 命令分割 Linux 文件”">​</a></h1><blockquote><p>一些简单的 Linux 命令能让你根据需要分割以及重新组合文件，来适应存储或电子邮件附件大小的限制。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/08/chocolate-chunks-100767935-large.jpg" alt="Marco Verch"></p><p>Linux 系统提供了一个非常易于使用的命令来分割文件。在将文件上传到限制大小的存储网站或者作为邮件附件之前，你可能需要执行此操作。要将文件分割为多个文件块，只需使用 <code>split</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ split bigfile</span></span></code></pre></div><p>默认情况下，<code>split</code> 命令使用非常简单的命名方案。文件块将被命名为 <code>xaa</code>、<code>xab</code>、<code>xac</code> 等，并且，大概地，如果你将足够大的文件分割，你甚至可能会得到名为 <code>xza</code> 和 <code>xzz</code> 的块。</p><p>除非你要求，否则该命令将无任何反馈地运行。但是，如果你想在创建文件块时看到反馈，可以使用 <code>--verbose</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ split –-verbose bigfile</span></span>
<span class="line"><span>creating file &#39;xaa&#39;</span></span>
<span class="line"><span>creating file &#39;xab&#39;</span></span>
<span class="line"><span>creating file &#39;xac&#39;</span></span></code></pre></div><p>你还可以给文件命名前缀。例如，要将你原始文件分割并命名为 <code>bigfile.aa</code>、<code>bigfile.ab</code> 等，你可以将前缀添加到 <code>split</code> 命令的末尾，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ split –-verbose bigfile bigfile.</span></span>
<span class="line"><span>creating file &#39;bigfile.aa&#39;</span></span>
<span class="line"><span>creating file &#39;bigfile.ab&#39;</span></span>
<span class="line"><span>creating file &#39;bigfile.ac&#39;</span></span></code></pre></div><p>请注意，上述命令中显示的前缀的末尾会添加一个点。否则，文件将是 <code>bigfileaa</code> 之类的名称，而不是 <code>bigfile.aa</code>。</p><p>请注意，<code>split</code> 命令<em>不会</em>删除你的原始文件，只是创建了文件块。如果要指定文件块的大小，可以使用 <code>-b</code> 选项将其添加到命令中。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ split -b100M bigfile</span></span></code></pre></div><p>文件大小可以是 KB、MB，GB，最大可以是 YB！只需使 K、M、G、T、P、E、Z 和 Y 这些合适的字母。</p><p>如果要基于每个块中的行数而不是字节数来拆分文件，那么可以使用 <code>-l</code>（行）选项。在此示例中，每个文件将有 1000 行，当然，最后一个文件可能有较少的行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ split --verbose -l1000 logfile log.</span></span>
<span class="line"><span>creating file &#39;log.aa&#39;</span></span>
<span class="line"><span>creating file &#39;log.ab&#39;</span></span>
<span class="line"><span>creating file &#39;log.ac&#39;</span></span>
<span class="line"><span>creating file &#39;log.ad&#39;</span></span>
<span class="line"><span>creating file &#39;log.ae&#39;</span></span>
<span class="line"><span>creating file &#39;log.af&#39;</span></span>
<span class="line"><span>creating file &#39;log.ag&#39;</span></span>
<span class="line"><span>creating file &#39;log.ah&#39;</span></span>
<span class="line"><span>creating file &#39;log.ai&#39;</span></span>
<span class="line"><span>creating file &#39;log.aj&#39;</span></span></code></pre></div><p>如果你需要在远程站点上重新组合文件，那么可以使用如下所示的 <code>cat</code> 命令轻松地完成此操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat x?? &gt; original.file</span></span>
<span class="line"><span>$ cat log.?? &gt; original.file</span></span></code></pre></div><p>上面所示的分割和组合命令适合于二进制和文本文件。在此示例中，我们将 zip 二进制文件分割为 50KB 的块，之后使用 <code>cat</code> 重新组合了它们，然后比较了组合后的文件和原始文件。<code>diff</code> 命令验证文件是否相同。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ split --verbose -b50K zip zip.</span></span>
<span class="line"><span>creating file &#39;zip.aa&#39;</span></span>
<span class="line"><span>creating file &#39;zip.ab&#39;</span></span>
<span class="line"><span>creating file &#39;zip.ac&#39;</span></span>
<span class="line"><span>creating file &#39;zip.ad&#39;</span></span>
<span class="line"><span>creating file &#39;zip.ae&#39;</span></span>
<span class="line"><span>$ cat zip.a? &gt; zip.new</span></span>
<span class="line"><span>$ diff zip zip.new</span></span>
<span class="line"><span>$                    &lt;== 无输出 = 无差别</span></span></code></pre></div><p>我唯一要提醒的一点的是，如果你经常使用 <code>split</code> 并使用默认命名，那么某些文件块可能会覆盖其他的文件块，甚至会比你预期的更多，因为有些是更早之前分割的。</p><hr>`,22)),l("p",null,[s[1]||(s[1]=i("via: ",-1)),e(a,{href:"https://www.networkworld.com/article/3489256/breaking-linux-files-into-pieces-with-the-split-command.html"},{default:n(()=>[...s[0]||(s[0]=[i("https://www.networkworld.com/article/3489256/breaking-linux-files-into-pieces-with-the-split-command.html",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=i("作者：",-1)),e(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...s[2]||(s[2]=[i("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=i(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 译者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:n(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[i("Linux中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const w=t(g,[["render",r]]);export{C as __pageData,w as default};
